{"explanation":"The sine graph is wavy because sine measures the height of a point moving around a circle. As the point turns, its height smoothly rises to 1, falls through 0 to −1, and rises again. Plotting that height against the angle creates a wave that repeats every full turn (2π radians). Drag either yellow point to see the connection.","manimCode":"let theta = Math.PI / 4;
const cx = -4.5;
const cy = 2.4;
const radius = 0.75;
const tau = 2 * Math.PI;

const title = new Text({ text: 'Sine is a rotating point’s height', fontSize: 28, color: WHITE });
title.moveTo([1, 3.25, 0]);
const circle = new Circle({ radius: radius, color: BLUE });
circle.moveTo([cx, cy, 0]);
const centerDot = new Dot({ point: [cx, cy, 0], radius: 0.04, color: GRAY });
const baseline = new Line({ start: [cx - radius, cy, 0], end: [cx + radius, cy, 0], color: GRAY });
const spoke = new Line({ start: [cx, cy, 0], end: [cx + radius, cy, 0], color: YELLOW });
const height = new Line({ start: [cx, cy, 0], end: [cx, cy + radius, 0], color: TEAL });
height.setStrokeWidth(5);
const projection = new DashedLine({ start: [cx, cy + radius, 0], end: [cx + radius, cy + radius, 0], color: TEAL });
const circleHandle = new Dot({ point: [cx + radius, cy, 0], radius: 0.12, color: YELLOW });
const circleCaption = new Text({ text: 'One turn = one wave', fontSize: 19, color: BLUE });
circleCaption.moveTo([cx, 1.4, 0]);

const axes = new Axes({ xRange: [-tau, tau, Math.PI / 2], yRange: [-1.5, 1.5, 0.5], xLength: 11, yLength: 2.6, tips: false });
const curve = axes.plot(x => Math.sin(x), { color: BLUE });
const upperGuide = new DashedLine({ start: axes.c2p(-tau, 1), end: axes.c2p(tau, 1), color: GRAY });
const lowerGuide = new DashedLine({ start: axes.c2p(-tau, -1), end: axes.c2p(tau, -1), color: GRAY });
upperGuide.setOpacity(0.35);
lowerGuide.setOpacity(0.35);
const graphHeight = new Line({ start: axes.c2p(theta, 0), end: axes.c2p(theta, Math.sin(theta)), color: TEAL });
graphHeight.setStrokeWidth(5);
const graphHandle = new Dot({ point: axes.c2p(theta, Math.sin(theta)), radius: 0.13, color: YELLOW });

const readout = new Text({ text: '', fontSize: 25, color: TEAL });
readout.moveTo([1.4, 2.45, 0]);
const meaning = new Text({ text: 'Horizontal: angle     Vertical: height', fontSize: 20, color: GRAY });
meaning.moveTo([1.4, 1.9, 0]);
const hint = new Text({ text: 'Drag either yellow point — both show the same angle', fontSize: 22, color: YELLOW });
hint.moveTo([0, -2.65, 0]);
const repeat = new Text({ text: 'Every full turn repeats the same rise and fall.', fontSize: 21, color: WHITE });
repeat.moveTo([0, -3.15, 0]);

scene.add(title, axes, upperGuide, lowerGuide, circle, baseline, centerDot, spoke, height, projection, circleCaption, readout, meaning, hint, repeat);
for (const [value, caption] of [[-tau, '−2π'], [-Math.PI, '−π'], [0, '0'], [Math.PI, 'π'], [tau, '2π']]) {
  const tickLabel = new Text({ text: caption, fontSize: 18, color: GRAY });
  tickLabel.moveTo(axes.c2p(value, -1.85));
  scene.add(tickLabel);
}
for (const value of [-1, 1]) {
  const heightLabel = new Text({ text: String(value), fontSize: 17, color: GRAY });
  heightLabel.moveTo(axes.c2p(-tau - 0.35, value));
  scene.add(heightLabel);
}

function update() {
  const sine = Math.sin(theta);
  const point = [cx + radius * Math.cos(theta), cy + radius * sine, 0];
  circleHandle.moveTo(point);
  spoke.setEnd(point);
  height.setStart([cx, cy, 0]);
  height.setEnd([cx, cy + radius * sine, 0]);
  projection.setStart([cx, cy + radius * sine, 0]);
  projection.setEnd(point);
  graphHandle.moveTo(axes.c2p(theta, sine));
  graphHeight.setStart(axes.c2p(theta, 0));
  graphHeight.setEnd(axes.c2p(theta, sine));
  readout.setText('Angle = ' + theta.toFixed(2) + ' rad     sin = ' + sine.toFixed(2));
}
update();
await scene.play(new Create(curve));
scene.add(graphHeight, graphHandle, circleHandle);

makeDraggable(circleHandle, scene, { onDrag: (mob, pos) => {
  const angle = Math.atan2(pos[1] - cy, pos[0] - cx);
  theta = angle < 0 ? angle + tau : angle;
  update();
} });
makeDraggable(graphHandle, scene, { onDrag: (mob, pos) => {
  theta = Math.max(0, Math.min(tau, axes.pointToCoords(pos)[0]));
  update();
} });
await scene.wait(999999);"}

